#!/usr/bin/env bash
set -euo pipefail
TASK_KIT_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$TASK_KIT_ROOT"
: "${DOCS_PYTHON:=python3.12}"
: "${DOCS_NODE:=node}"
# The starter is generated by init, as users get it, then built and linted.
STARTER="$TASK_KIT_ROOT/.build/starter"
rm -rf "$STARTER"
mkdir -p "$STARTER"
git -C "$STARTER" init -q
"$DOCS_PYTHON" docsite.py init "$STARTER" --title "Documentation kit"
git -C "$STARTER" add -A
export DOCSITE_PROJECT_ROOT="$STARTER"
export PYTHONPATH="$TASK_KIT_ROOT/tooling"
"$DOCS_PYTHON" docsite.py build --project "$STARTER"
"$DOCS_PYTHON" docsite.py lint --project "$STARTER" --strict
"$DOCS_PYTHON" -m unittest discover -s tests -p 'test_*.py'
# The kit's own reference website, built from the repository root.
DOCSITE_PROJECT_ROOT="$TASK_KIT_ROOT" "$DOCS_PYTHON" docsite.py build --project .
DOCSITE_PROJECT_ROOT="$TASK_KIT_ROOT" "$DOCS_PYTHON" docsite.py lint --project . --strict
"$DOCS_NODE" tests/test_math_runtime.cjs
"$DOCS_NODE" tests/test_site_filelinks.cjs
# Reader, fold-control and panel-switcher logic in a fake DOM; no browser needed.
"$DOCS_NODE" tests/test_reader_logic.cjs
"$DOCS_NODE" tests/test_panel_switcher_logic.cjs
# Page lock: Node's WebCrypto must open what the Python side sealed. Its checks
# need the optional cryptography package from requirements-lock.txt.
if "$DOCS_PYTHON" -c "import cryptography" 2>/dev/null; then
  lock_checks=1
  DOCS_PYTHON="$DOCS_PYTHON" "$DOCS_NODE" tests/test_page_lock_webcrypto.cjs
elif [ "${DOCS_REQUIRE_BROWSER:-0}" = 1 ]; then
  echo "ERROR: the page-lock checks need cryptography. Run python -m pip install -r requirements-lock.txt." >&2
  exit 1
else
  lock_checks=0
  echo "SKIPPED: page-lock checks. Run python -m pip install -r requirements-lock.txt to run them."
fi
# Every shared script must parse, even where no browser is available.
scripts=(theme/components/*.js tooling/*.cjs tests/*.cjs)
for script in "${scripts[@]}"; do
  "$DOCS_NODE" --check "$script"
done
echo "Syntax: ${#scripts[@]} scripts parse."
# Real-browser suites: starter reader, layout helpers, panel switcher and the
# kit's own site. They load Playwright from the kit's own node_modules, which
# `npm ci` installs from package.json and package-lock.json, and run when it
# loads. DOCS_REQUIRE_BROWSER=1 makes a missing install fail instead of
# skipping, as the Pages workflow does.
if "$DOCS_NODE" -e "require('./node_modules/playwright')" 2>/dev/null; then
  cap=()
  if systemd-run --user --scope --quiet -p MemoryMax=4G -p MemorySwapMax=0 true 2>/dev/null; then
    cap=(systemd-run --user --scope --quiet -p MemoryMax=4G -p MemorySwapMax=0)
  fi
  # Only the suite gets the unreachable bus address, which keeps Chromium away
  # from the desktop session; systemd-run itself still needs the real one.
  # test_reference_tree builds its own fixture above the inline Reference limit.
  for suite in visual_review test_browser_checks test_panel_switcher own_site_review test_reference_tree; do
    ${cap[@]+"${cap[@]}"} env DBUS_SESSION_BUS_ADDRESS="unix:path=/nonexistent-docs-kit-review" DOCS_PYTHON="$DOCS_PYTHON" \
      timeout 280 "$DOCS_NODE" "tests/$suite.cjs"
  done
  if [ "$lock_checks" = 1 ]; then
    ${cap[@]+"${cap[@]}"} env DBUS_SESSION_BUS_ADDRESS="unix:path=/nonexistent-docs-kit-review" \
      DOCS_PYTHON="$DOCS_PYTHON" timeout 280 "$DOCS_NODE" tests/test_page_lock_browser.cjs
  fi
elif [ "${DOCS_REQUIRE_BROWSER:-0}" = 1 ]; then
  echo "ERROR: browser suites are required, but Playwright does not load from node_modules/. Run npm ci." >&2
  exit 1
else
  echo "SKIPPED: browser suites (starter reader, layout helpers, panel switcher, own site, Reference tree)."
  echo "         Run npm ci and npx playwright install chromium to run them."
fi
